#include <iostream>
#include <cstdio>
#include <string>
#include <vector>
#include <array>
using std::cin;
using std::cout;
using std::cerr;
using std::endl;
using std::string;
using std::pair;
using std::vector;
using std::min;
using std::max;
using std::array;
#include <atcoder/all>

typedef long long int ll;

ll n, m;
vector<ll> x;

void solve () {
	sort(x.begin(), x.end());

	vector<ll> d;
	for (ll i = 0; i < n-1; i++) {
		d.push_back(x[i+1] - x[i]);
	}
	sort(d.begin(), d.end());

	ll ans = 0;
	for (ll i = 0; i < n-m; i++) {
		ans += d[i];
	}

	cout << ans << "\n";
}

int main (void) {
	std::ios_base::sync_with_stdio(false);
	cin.tie(nullptr);

	cin >> n >> m;
	x.resize(n);
	for (ll i = 0; i < n; i++) {
		cin >> x[i];
	}

	solve();

	return 0;
}
